test("W1-T10879: the later reviewed worker fingerprint remains exact", () => {
  const source = gunzipSync(Buffer.from(REVIEWED_MAIN_SOURCE_GZIP, "base64")).toString("utf8");
  assert.equal(createHash("sha256").update(source).digest("hex"), "3c13d145270b0d9e7c75d243b7253dfeda21bd1e137b496b9eaf5fabdc559fea");
  const fingerprint = createHash("sha256").update(JSON.stringify(executableTokens(source))).digest("hex");
  assert.equal(fingerprint, REVIEWED_TOKENS_SHA256, "the later reviewed executable tokens remain exact");
  const { comments } = countCommentLines(source, "src/lib/worker.ts");
  assert.ok(comments < BEFORE_COMMENT_LINES, `expected a real reduction from ${BEFORE_COMMENT_LINES} comment lines, observed ${comments}`);
});

test("W1-T10879: current worker retains the maintained comment reduction", () => {
  const source = readFileSync(join(REPO_ROOT, "src/lib/worker.ts"), "utf8");
  const { comments } = countCommentLines(source, "src/lib/worker.ts");
  assert.ok(comments < BEFORE_COMMENT_LINES, `expected a real reduction from ${BEFORE_COMMENT_LINES} comment lines, observed ${comments}`);
});
